//! D1 reference oracles for R18.4: Custom DSL Built-In Functions (§4.1) and
//! `[InitialValues]` Rule Grammar (§4.2).
//!
//! D1 Provenance:
//! - Independent reference values generated by `R 4.5.2 (2025-10-31)` via
//!   `crates/fit/tests/reference/r18_4_dsl_builtins.R`.
//! - Mathematical definitions: Abramowitz & Stegun (1964) §§6, 9.8, 26.5;
//!   NIST DLMF §§8.17, 10.25–10.35; Finney (1971) probit scale `5 + Phi^-1(p)`.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::excessive_precision)]

use super::common;

use curvebook_fit::{DataPoint, FitStatus, ParametricModel};
use curvebook_testkit::assert_approx_eq;

use common::{assert_dsl_compile_err, dsl_compile, fit_default, series_from_pts};

fn eval_dsl(expr: &str, x: &[f64]) -> Option<f64> {
    dsl_compile(expr).eval(x, &[], 0)
}

fn assert_eval_oracles(cases: &[(&str, f64, f64)]) {
    for &(expr, expected, tol) in cases {
        let actual = eval_dsl(expr, &[0.0]).unwrap_or_else(|| panic!("expected Some for `{expr}`"));
        assert_approx_eq(actual, expected, tol, tol, expr);
    }
}

fn assert_eval_none(exprs: &[&str]) {
    for &expr in exprs {
        assert!(eval_dsl(expr, &[0.0]).is_none(), "expected None for `{expr}`");
    }
}

#[test]
fn d1_r18_4_incomplete_beta_and_gamma_oracles() {
    assert_eval_oracles(&[
        ("Y = ibeta(2.5, 3.5, 0.4)", 4.869_041_915_261_175_8e-1, 1e-13),
        ("Y = ibeta(0.5, 0.5, 0.25)", 3.333_333_333_333_332_6e-1, 1e-13),
        ("Y = ibeta(12.0, 8.0, 0.72)", 8.662_193_673_584_953_6e-1, 1e-13),
        ("Y = igamma(2.5, 1.8)", 3.916_867_079_185_313_9e-1, 1e-13),
        ("Y = igammac(2.5, 1.8)", 6.083_132_920_814_685_6e-1, 1e-13),
        ("Y = igamma(10.0, 15.0)", 9.301_463_393_005_902_1e-1, 1e-13),
        ("Y = igammac(10.0, 15.0)", 6.985_366_069_940_977_8e-2, 1e-13),
    ]);
    assert_eval_none(&["Y = ibeta(0, 1, 0.5)", "Y = ibeta(1, 1, -0.1)", "Y = igamma(0, 1)", "Y = igammac(2, -1)"]);
}

