#[test]
fn d1_r18_4_helpers_bessel_and_aliases_oracles() {
    assert_eval_oracles(&[
        ("Y = fact(0)", 1.0, 1e-15),
        ("Y = fact(12)", 4.790_016_000_000_000e8, 1e-12),
        ("Y = fact(100)", 9.332_621_544_394_224_9e157, 1e-12),
        ("Y = logit(0.2)", -1.386_294_361_119_890_6, 1e-14),
        ("Y = logit(0.999)", 6.906_754_778_648_553, 1e-12),
        ("Y = probit(0.5)", 5.0, 1e-14),
        ("Y = probit(0.975)", 6.959_963_984_540_053, 1e-12),
        ("Y = probit(0.1)", 3.718_448_434_455_399_2, 1e-12),
        ("Y = perc(37.5)", 0.375, 1e-15),
        ("Y = deg(PI / 2)", 90.0, 1e-13),
        ("Y = rad(180)", std::f64::consts::PI, 1e-14),
        ("Y = sqr(-3.5)", 12.25, 1e-15),
        ("Y = int(-3.9)", -3.0, 1e-15),
        ("Y = int(3.9)", 3.0, 1e-15),
        ("Y = sgn(-4.2)", -1.0, 1e-15),
        ("Y = mod(17.5, 5)", 2.5, 1e-15),
        ("Y = besseli(0, 2.5)", 3.289_839_144_050_122_7, 1e-12),
        ("Y = besseli(1, 2.5)", 2.516_716_245_288_698_4, 1e-12),
        ("Y = besseli(3, 2.5)", 4.743_704_087_780_355_5e-1, 1e-12),
        ("Y = besseli(-3, 2.5)", 4.743_704_087_780_355_5e-1, 1e-12),
        ("Y = besseli(3, -2.5)", -4.743_704_087_780_355_5e-1, 1e-12),
        ("Y = besseli(4, -2.5)", 1.379_771_667_518_788_5e-1, 1e-12),
        ("Y = besseli(5, 30.0)", 5.121_514_654_769_350e11, 1e-11),
        ("Y = besseli(10, 40.0)", 4.228_469_210_516_758_5e15, 1e-11),
        ("Y = besseli(0, 0)", 1.0, 1e-15),
        ("Y = besseli(3, 0)", 0.0, 1e-15),
        // K_0/K_1 use A&S 9.8.5–9.8.8 (~1e-7 accuracy), inherited by upward recurrence for K_n.
        ("Y = besselk(0, 1.5)", 2.138_055_626_475_257_3e-1, 1e-6),
        ("Y = besselk(1, 1.5)", 2.773_878_004_568_438_0e-1, 1e-6),
        ("Y = besselk(3, 1.5)", 1.833_803_702_474_579_2, 1e-6),
        ("Y = besselk(-3, 1.5)", 1.833_803_702_474_579_2, 1e-6),
        ("Y = besselk(5, 4.0)", 1.543_425_487_259_971_2e-1, 1e-6),
    ]);
    assert_approx_eq(eval_dsl("Y = X mod 5", &[17.5]).unwrap(), 2.5, 1e-15, 1e-15, "infix mod");
    assert_eval_none(&[
        "Y = fact(-1)",
        "Y = fact(2.5)",
        "Y = fact(171)",
        "Y = logit(0)",
        "Y = logit(1)",
        "Y = probit(0)",
        "Y = probit(1)",
        "Y = mod(5, 0)",
        "Y = besselk(2, 0)",
        "Y = besselk(2, -1)",
        "Y = besseli(100001, 2.0)",
        "Y = besselk(100001, 2.0)",
    ]);

    let mv = dsl_compile("Y = IF(is_defined(X2), 2 * X1 + 3 * X2, 2 * X1)");
    assert_eq!(mv.param_names(), &[] as &[String]);
    for (xs, exp, lbl) in [([4.0, 5.0], 23.0, "finite"), ([4.0, f64::NAN], 8.0, "NaN"), ([4.0, f64::INFINITY], 8.0, "Inf")] {
        assert_approx_eq(mv.eval(&xs, &[], 0).unwrap(), exp, 1e-15, 1e-15, &format!("is_defined {lbl}"));
    }

    for (a, b) in [
        ("Y = gammaln(5.5)", "Y = lngamma(5.5)"),
        ("Y = hypgeometricm(1.5, 2.5, 1.2)", "Y = hyp1f1(1.5, 2.5, 1.2)"),
        ("Y = hypgeometricu(1.5, 2.5, 1.2)", "Y = confluent_u(1.5, 2.5, 1.2)"),
        ("Y = hypgeometricf(0.5, 1.5, 2.5, 0.3)", "Y = hyp2f1(0.5, 1.5, 2.5, 0.3)"),
    ] {
        assert_approx_eq(eval_dsl(a, &[0.0]).unwrap(), eval_dsl(b, &[0.0]).unwrap(), 1e-15, 1e-15, &format!("{a} == {b}"));
    }
}

#[test]
fn d1_r18_4_initial_values_rule_grammar_anchors_and_titles() {
    let model = dsl_compile(
        "[Equation]\nY = P0 + P1 * X + P2 + P3 + P4 + P5 + P6 + P7 + P8 + P9 + P10\n[InitialValues]\n\
         P0 = 4.5 * (InitialValue)\nP1 = 2 * YMIN\nP2 = 0.5 * YMAX\nP3 = 1 * YMID\nP4 = 1 * XatYmid\n\
         P5 = 1 * YatXmin\nP6 = 1 * YatXmid\nP7 = 1 * YatXmax\nP8 = SIGN(YatXmax - YatXmin)\n\
         P9 = 2 * MeanColumnTitle\nP10 = 1 * LogMeanColumnTitle\n",
    );
    let pts = vec![DataPoint::xy(0.0, 19.0), DataPoint::xy(0.0, 21.0), DataPoint::xy(2.0, 16.0), DataPoint::xy(6.0, 8.0), DataPoint::xy(10.0, 0.0)];
    let titles = [10.0, 100.0, 190.0];
    let init = model.initial_guess_with_column_titles(&pts, &titles);
    for (i, (exp, tol, lbl)) in [
        (4.5, 1e-14, "c * (InitialValue)"),
        (0.0, 1e-14, "2 * YMIN"),
        (10.5, 1e-14, "0.5 * YMAX"),
        (10.5, 1e-14, "YMID"),
        (4.75, 1e-12, "XatYmid"),
        (20.0, 1e-14, "YatXmin"),
        (10.0, 1e-14, "YatXmid"),
        (0.0, 1e-14, "YatXmax"),
        (-1.0, 1e-14, "SIGN(YatXmax - YatXmin)"),
        (200.0, 1e-14, "2 * MeanColumnTitle"),
        (2.0, 1e-14, "LogMeanColumnTitle"),
    ]
    .into_iter()
    .enumerate()
    {
        assert_approx_eq(init[i], exp, tol, tol, lbl);
    }

    let via_trait = model.clone().with_column_title_values(titles.to_vec()).initial_guess(&pts);
    assert_approx_eq(via_trait[9], 200.0, 1e-14, 1e-14, "bound MeanColumnTitle");
    assert_approx_eq(via_trait[10], 2.0, 1e-14, 1e-14, "bound LogMeanColumnTitle");

    let no_titles = model.initial_guess(&pts);
    assert_approx_eq(no_titles[9], 1.0, 1e-14, 1e-14, "fallback MeanColumnTitle");
    assert_approx_eq(no_titles[10], 1.0, 1e-14, 1e-14, "fallback LogMeanColumnTitle");
}

#[test]
fn d1_r18_4_initial_values_empirical_slopes_oracles() {
    let model = dsl_compile(
        "[Equation]\nY = SMin * X + SMid + SMax + RMin + RMid + RMax\n[InitialValues]\n\
         SMin = 1 * SlopeAtXmin\nSMid = 1 * SlopeAtXmid\nSMax = 1 * SlopeAtXmax\n\
         RMin = 2 / SlopeAtXmin\nRMid = 2 / SlopeAtXmid\nRMax = 2 / SlopeAtXmax\n",
    );

    // Case 1: N = 40 >= 30, k = 4, deliberately unsorted
    let pts40: Vec<DataPoint> = (0..40)
        .rev()
        .map(|i| {
            let x = f64::from(i);
            DataPoint::xy(x, 0.05 * x * x - 1.2 * x + 3.0)
        })
        .collect();
    let init40 = model.initial_guess(&pts40);
    for (i, exp) in [-1.05, 0.75, 2.55, 2.0 / -1.05, 2.0 / 0.75, 2.0 / 2.55].into_iter().enumerate() {
        assert_approx_eq(init40[i], exp, 1e-13, 1e-13, &format!("init40[{i}]"));
    }

    // Case 2 (N = 7 odd: 3-pt OLS) and Case 3 (N = 6 even: 2-pt secant), y = x^2
    for (xs, expected, tol, lbl) in [
        (&[0.0, 1.0, 2.0, 3.0, 5.0, 7.0, 10.0][..], [1.0, 7.142_857_142_857_146, 17.0], 1e-12, "n7"),
        (&[0.0, 1.0, 2.0, 4.0, 7.0, 10.0][..], [1.0, 6.0, 17.0], 1e-13, "n6"),
    ] {
        let pts: Vec<DataPoint> = xs.iter().map(|&x| DataPoint::xy(x, x * x)).collect();
        let init = model.initial_guess(&pts);
        for (i, exp) in expected.into_iter().enumerate() {
            assert_approx_eq(init[i], exp, tol, tol, &format!("{lbl}[{i}]"));
        }
    }
}

#[test]
fn d1_r18_4_end_to_end_custom_fit_with_new_builtins_and_init_rules() {
    let model = dsl_compile(
        "[Equation]\nY = Bottom + (Top - Bottom) * normdist(X, Mu, Sigma)\n[InitialValues]\n\
         Bottom = 1 * YatXmin\nTop = 1 * YatXmax\nMu = 1 * XatYmid\nSigma = 0.25 * (XMAX - XMIN)\n",
    );
    let true_params = [10.0, 90.0, 5.0, 1.5];
    let points: Vec<DataPoint> = (0..25)
        .map(|i| {
            let x = 0.5 * f64::from(i);
            DataPoint::xy(x, model.eval(&[x], &true_params, 0).unwrap())
        })
        .collect();
    let res = fit_default(&model, &[series_from_pts(0, "CumulativeNormal", points)]);
    assert_eq!(res.status, FitStatus::Converged);
    for ((&val, name), &truth) in res.datasets[0].params.iter().zip(&res.datasets[0].param_names).zip(&true_params) {
        assert_approx_eq(val, truth, 1e-6, 1e-6, name);
    }
}
